import yaml,glob,os
c=yaml.safe_load(open('docs/data_contract.yaml'))['modeling_spec']
for layer in ['intermediate','marts']:
 files={os.path.basename(x)[:-4] for x in glob.glob('sql/'+layer+'/**/*.sql',recursive=True)}
 expect={m['name'] for m in c[layer+'_models']}
 print(layer,'missing',expect-files,'extra',files-expect)
print('staging',len(glob.glob('sql/staging/*.sql')))
